package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.*;
import dev.tacticalcombat.character.*;
import java.nio.file.*;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

public final class HudUiTests {
    private static int count;
    private static void check(boolean ok,String reason){count++;if(!ok)throw new AssertionError(reason);}
    private static JsonObject page(UUID session,List<UiEvents.Event> events,long cursor){return SheetSections.JSON.toJsonTree(new UiEvents.Page(session,events,cursor,1,false)).getAsJsonObject();}
    private static UiEvents.Event event(long sequence,UUID campaign,UUID actor,UiEvents.Roll roll){return new UiEvents.Event(UUID.randomUUID(),sequence,1,campaign,null,1,roll==null?UiEvents.Kind.TURN:UiEvents.Kind.DICE,List.of(actor),"Server event",roll,UiEvents.Visibility.CAMPAIGN,Set.of());}
    private static void rejects(Runnable task,String reason){try{task.run();}catch(RuntimeException expected){count++;return;}throw new AssertionError(reason);}
    public static void run()throws Exception{
        var model=new HudSession();UUID campaign=UUID.randomUUID(),actor=UUID.randomUUID(),session=UUID.randomUUID();model.campaign(campaign.toString());
        var member=args("character",UUID.randomUUID(),"skinPlayer",actor,"name","Pierre","characterClass","Fighter","online",true,"inCombat",false);
        model.party(args("hpVisibility","PRIVATE","members",arrayOf(member)));check(model.members().size()==1&&model.members().getFirst().health().equals("HP private")&&model.members().getFirst().fraction()==-1,"private HP has no invented value");
        member.addProperty("healthFraction",.5);model.party(args("members",arrayOf(member)));check(model.members().getFirst().fraction()==.5&&model.members().getFirst().health().equals("HP bar"),"bars remain fraction only");
        member.addProperty("hp",12);member.addProperty("maximumHp",24);model.party(args("members",arrayOf(member)));check(model.members().getFirst().health().equals("12/24 HP"),"exact authorized HP projected");member.addProperty("online",false);model.party(args("members",arrayOf(member)));check(!model.members().getFirst().online(),"offline flag remains server-derived");
        var initiative=args("active",actor,"round",3,"actors",arrayOf(args("id",actor,"name","Pierre","initiative",15),args("id",UUID.randomUUID(),"name","Tie","initiative",15)));model.initiative("encounter",initiative);check(model.actors().getFirst().active()&&model.actors().getLast().name().equals("Tie"),"server tie ordering retained");check(model.round()==3,"round supplied by server");model.endEncounter();check(model.actors().isEmpty()&&model.round()==0,"initiative hidden after encounter");
        UiEvents.Roll advantage=UiEvents.Roll.from(20,List.of(18,7),1,5,"Attack",false),disadvantage=UiEvents.Roll.from(20,List.of(18,7),2,5,"Attack",false);check(advantage.total()==23&&advantage.kept().equals(List.of(0))&&disadvantage.total()==12&&disadvantage.kept().equals(List.of(1)),"raw faces kept indices and modified totals remain distinct");
        check(HudSession.natural(UiEvents.Roll.from(20,List.of(15),0,5,"Check",false))==15,"total 20 does not imply natural 20");check(HudSession.natural(UiEvents.Roll.from(20,List.of(20),0,-1,"Attack",true))==20,"natural 20 independent of modifier");check(HudSession.natural(UiEvents.Roll.from(20,List.of(1),0,19,"Check",false))==1,"natural 1 independent of total");
        var old=event(1,campaign,actor,advantage);model.events(page(session,List.of(old),1),10,80);check(model.history(HudSession.Filter.ALL).size()==1&&model.nextDice()==null,"initial history restored without animations");var live=event(2,campaign,actor,advantage);model.events(page(session,List.of(live),2),20,80);check(model.queuedDice()==1&&model.bubble(actor.toString(),20).text().contains("23"),"live roll queued once with party bubble");model.events(page(session,List.of(live),2),21,80);check(model.queuedDice()==1&&model.history(HudSession.Filter.DICE).size()==2,"duplicate event cannot animate or log twice");check(model.nextDice().id().equals(live.id()),"authoritative identity preserved");check(model.bubble(actor.toString(),101)==null,"party bubble expires");
        var burst=new ArrayList<UiEvents.Event>();for(int i=3;i<23;i++)burst.add(event(i,campaign,actor,advantage));feed(model,session,burst,30);check(model.queuedDice()==8&&model.history(HudSession.Filter.ALL).size()==22,"bounded dice queue retains complete received history");
        var turns=new ArrayList<UiEvents.Event>();for(int i=23;i<43;i++)turns.add(event(i,campaign,actor,null));feed(model,session,turns,40);check(model.queuedNotices()==8,"notifications bounded");check(model.history(HudSession.Filter.COMBAT).size()==20&&model.history(HudSession.Filter.REST).isEmpty(),"event filters only use genuine event types");
        model.revalidateHistory();model.events(page(session,List.of(old,live),2),50,80);check(model.nextDice()==null&&model.history(HudSession.Filter.ALL).size()==2,"reauthorization history does not replay old dice");model.events(page(UUID.randomUUID(),List.of(old),1),60,80);check(model.nextDice()==null&&model.history(HudSession.Filter.ALL).size()==1,"new server session resets history and bootstrap");model.campaign(UUID.randomUUID().toString());check(model.history(HudSession.Filter.ALL).isEmpty()&&model.members().isEmpty()&&model.actors().isEmpty(),"campaign change clears all private projections");
        for(int[] size:new int[][]{{320,180},{427,240},{854,480},{1920,1080}})for(double scale:List.of(.5,1.,2.))for(double x:List.of(0.,.5,1.)){var r=HudSession.bounds(new HudPreferences.Panel(x,1,scale,true),size[0],size[1],270,130);check(r.fits(size[0],size[1]),"panels recover onscreen after resolution and scale changes");}
        var dir=Files.createTempDirectory("hud-options");var opts=HudOptions.defaults();opts.save(dir.resolve("options.json"));check(HudOptions.load(dir.resolve("options.json")).equals(opts),"additional options persist locally");var prefs=HudPreferences.defaults();prefs.save(dir.resolve("layout.json"));check(HudPreferences.load(dir.resolve("layout.json")).equals(prefs),"existing version-1 layout roundtrips");check(prefs.party().x()==0&&prefs.party().y()==0&&prefs.initiative().x()==.5,"compact approved default anchors");rejects(()->new HudPreferences.Panel(2,0,1,true),"offscreen fractions rejected");rejects(()->new HudPreferences.Panel(0,0,3,true),"scale bounds enforced");
        var repo=new CharacterRepository(dir.resolve("campaigns.json"));var dm=new CharacterRepository.Principal(UUID.randomUUID(),true);var peer=new CharacterRepository.Principal(UUID.randomUUID(),false);var denied=new CharacterRepository.Principal(UUID.randomUUID(),false);UUID id=repo.createCampaign(dm,"Shared dice");repo.invite(dm,id,1,peer.id(),false);repo.invite(dm,id,2,denied.id(),false);var history=new UiEvents();UUID shared=UUID.randomUUID();history.publish(shared,id,null,0,UiEvents.Kind.DICE,List.of(peer.id()),"Shared roll",advantage,UiEvents.Visibility.RECIPIENTS_AND_DM,Set.of(peer.id()));HudSession a=new HudSession(),b=new HudSession(),c=new HudSession();for(var m:List.of(a,b,c))m.events(page(history.query(repo,dm,id,0,null).session(),List.of(),0),0,80);a.events(SheetSections.JSON.toJsonTree(history.query(repo,peer,id,0,null)).getAsJsonObject(),1,80);b.events(SheetSections.JSON.toJsonTree(history.query(repo,dm,id,0,null)).getAsJsonObject(),1,80);c.events(SheetSections.JSON.toJsonTree(history.query(repo,denied,id,0,null)).getAsJsonObject(),1,80);check(a.nextDice().id().equals(shared)&&b.nextDice().id().equals(shared),"eligible recipients animate same server event identity");check(c.history(HudSession.Filter.ALL).isEmpty()&&c.nextDice()==null,"unauthorized peer receives no secret faces or modifiers");
        var compact=HudPreferences.defaults();var compactParty=HudSession.bounds(compact.party(),320,180,174,78);var compactInit=HudSession.initiativeBounds(compact,320,180,compactParty);check(compactInit.fits(320,180)&&!compactInit.overlaps(compactParty),"compact default initiative avoids party panel");
        var overflow=new ArrayList<UiEvents.Event>();for(int i=100;i<650;i++)overflow.add(event(i,campaign,actor,null));feed(model,session,overflow,100);check(model.historySize()==512,"client event history bounded at server retention size");long before=model.viewVersion();feed(model,session,List.of(event(650,campaign,actor,null)),101);check(model.historySize()==512&&model.viewVersion()>before,"full log still signals newest events");
        System.out.println("HUD presentation checks passed: "+count);
    }
    private static JsonArray arrayOf(JsonObject... rows){var a=new JsonArray();for(var row:rows)a.add(row);return a;}
    private static void feed(HudSession model,UUID session,List<UiEvents.Event> rows,long now){for(int i=0;i<rows.size();i+=16){var chunk=rows.subList(i,Math.min(rows.size(),i+16));model.events(page(session,chunk,chunk.getLast().sequence()),now,80);}}
}
